function model = dual_arm_reduced_xy_model() 

import casadi.*

%% system dimensions

nx = 12;
nu = 4;

%% system parameters

% Kinematic parameters
LC = 4.26;
off = 0.19;
lArm = 0.808;

% Viscous friction
fvCx = 485.3;
fvCy = 52.7;            
fvA1 = 15;
fvA2 = 12;

% Static friction
% fsC = 0.767*0;
% fsA = 10*0;

% Gravity acceleration
g0 = 9.8;

% Masses 
mA1 = 7.1;
mA2 = 10.2;
mC = 191.8;

% CoM position 
lCz = 3.64;
lA1z = 0.051;
lA2z = 0.4157;

% Inertias
iC1xx = 35.87;
iC1yy = 0.01;
iC1zz = 0.01;
iC2xx = 0.01;
iC2yy = 58.23;
iC2zz = 0.01;

iA1xx = 3.53e-2;
iA1yy = 3.01e-2;
iA1zz = 1.87e-2;


iA2xx = 0.380;
iA2yy = 0.417;
iA2zz = 0.054;


%% named symbolic variables
qCx = SX.sym('qCx');
qCy = SX.sym('qCy');
qAL1 = SX.sym('qAL1');
qAL2 = SX.sym('qAL2');
qAR1 = SX.sym('qAR1');
qAR2 = SX.sym('qAR2');

qCxd = SX.sym('qCxd');
qCyd = SX.sym('qCyd');
qAL1d = SX.sym('qAL1d');
qAL2d = SX.sym('qAL2d');
qAR1d = SX.sym('qAR1d');
qAR2d = SX.sym('qAR2d');

yAL1 = SX.sym('yAL1');
yAL2 = SX.sym('yAL2');
yAR1 = SX.sym('yAR1');
yAR2 = SX.sym('yAR2');

%% (unnamed) symbolic variables
sym_x = vertcat(qCx, qCy, qAL1, qAL2, qAR1, qAR2, qCxd, qCyd, qAL1d, qAL2d, qAR1d ,qAR2d);
sym_xdot = SX.sym('xdot', nx, 1);
sym_u = vertcat(yAL1, yAL2, yAR1, yAR2);

%% dynamics

B = SX.sym('B',nx/2,nx/2);
n = SX.sym('n',nx/2,1);

B(1,1) = 2*iA2xx + 2*iA1zz + iC1xx + iC2zz + 2*lA2z^2*mA2 + (lCz^2*mC)/2 + 2*mA1*off^2 + 2*mA2*off^2 - iA2xx*cos(qAL2)^2 + iA2zz*cos(qAL2)^2 - iA2xx*cos(qAR2)^2 + iA2zz*cos(qAR2)^2 - 2*iA2xx*cos(qCy)^2 + 2*iA1yy*cos(qCy)^2 + 2*iA2yy*cos(qCy)^2 - 2*iA1zz*cos(qCy)^2 + iC2xx*cos(qCy)^2 - iC2zz*cos(qCy)^2 + iA1xx*cos(qAL1)^2*cos(qCy)^2 + iA2xx*cos(qAL2)^2*cos(qCy)^2 - iA1yy*cos(qAL1)^2*cos(qCy)^2 - iA2yy*cos(qAL1)^2*cos(qCy)^2 + iA2zz*cos(qAL1)^2*cos(qCy)^2 - iA2zz*cos(qAL2)^2*cos(qCy)^2 + iA1xx*cos(qAR1)^2*cos(qCy)^2 + iA2xx*cos(qAR2)^2*cos(qCy)^2 - iA1yy*cos(qAR1)^2*cos(qCy)^2 - iA2yy*cos(qAR1)^2*cos(qCy)^2 + iA2zz*cos(qAR1)^2*cos(qCy)^2 - iA2zz*cos(qAR2)^2*cos(qCy)^2 + 2*LC^2*mA1*cos(qCy)^2 + 2*LC^2*mA2*cos(qCy)^2 - lA2z^2*mA2*cos(qAL2)^2 - lA2z^2*mA2*cos(qAR2)^2 + 2*lA1z^2*mA1*cos(qCy)^2 + (lCz^2*mC*cos(qCy)^2)/2 - lA2z^2*mA2*cos(qAL1)^2*cos(qCy)^2 + lA2z^2*mA2*cos(qAL2)^2*cos(qCy)^2 - lA2z^2*mA2*cos(qAR1)^2*cos(qCy)^2 + lA2z^2*mA2*cos(qAR2)^2*cos(qCy)^2 + iA2xx*cos(qAL1)^2*cos(qAL2)^2*cos(qCy)^2 - iA2zz*cos(qAL1)^2*cos(qAL2)^2*cos(qCy)^2 + iA2xx*cos(qAR1)^2*cos(qAR2)^2*cos(qCy)^2 - iA2zz*cos(qAR1)^2*cos(qAR2)^2*cos(qCy)^2 + 4*LC*lA1z*mA1*cos(qCy)^2 + lA2z^2*mA2*cos(qAL1)^2*cos(qAL2)^2*cos(qCy)^2 + lA2z^2*mA2*cos(qAR1)^2*cos(qAR2)^2*cos(qCy)^2 + 2*lA2z*mA2*off*sin(qAL1)*sin(qAL2) + 2*lA2z*mA2*off*sin(qAR1)*sin(qAR2) + 2*LC*lA2z*mA2*cos(qAL2)*cos(qCy)^2 + 2*LC*lA2z*mA2*cos(qAR2)*cos(qCy)^2 - 2*iA2xx*cos(qAL1)*cos(qAL2)*cos(qCy)*sin(qAL2)*sin(qCy) + 2*iA2zz*cos(qAL1)*cos(qAL2)*cos(qCy)*sin(qAL2)*sin(qCy) + 2*iA2xx*cos(qAR1)*cos(qAR2)*cos(qCy)*sin(qAR2)*sin(qCy) - 2*iA2zz*cos(qAR1)*cos(qAR2)*cos(qCy)*sin(qAR2)*sin(qCy) - 2*lA2z^2*mA2*cos(qAL1)*cos(qAL2)*cos(qCy)*sin(qAL2)*sin(qCy) + 2*lA2z^2*mA2*cos(qAR1)*cos(qAR2)*cos(qCy)*sin(qAR2)*sin(qCy) - 2*LC*lA2z*mA2*cos(qAL1)*cos(qCy)*sin(qAL2)*sin(qCy) + 2*LC*lA2z*mA2*cos(qAR1)*cos(qCy)*sin(qAR2)*sin(qCy);
B(1,2) = iA1yy*cos(qAL1)*cos(qCy)*sin(qAL1) - iA1xx*cos(qAL1)*cos(qCy)*sin(qAL1) + iA2yy*cos(qAL1)*cos(qCy)*sin(qAL1) - iA2zz*cos(qAL1)*cos(qCy)*sin(qAL1) - iA1xx*cos(qAR1)*cos(qCy)*sin(qAR1) + iA1yy*cos(qAR1)*cos(qCy)*sin(qAR1) + iA2yy*cos(qAR1)*cos(qCy)*sin(qAR1) - iA2zz*cos(qAR1)*cos(qCy)*sin(qAR1) + lA2z^2*mA2*cos(qAL1)*cos(qCy)*sin(qAL1) + lA2z^2*mA2*cos(qAR1)*cos(qCy)*sin(qAR1) + iA2xx*cos(qAL2)*sin(qAL1)*sin(qAL2)*sin(qCy) - iA2zz*cos(qAL2)*sin(qAL1)*sin(qAL2)*sin(qCy) - iA2xx*cos(qAR2)*sin(qAR1)*sin(qAR2)*sin(qCy) + iA2zz*cos(qAR2)*sin(qAR1)*sin(qAR2)*sin(qCy) + lA2z*mA2*off*cos(qAL2)*sin(qCy) - lA2z*mA2*off*cos(qAR2)*sin(qCy) - iA2xx*cos(qAL1)*cos(qAL2)^2*cos(qCy)*sin(qAL1) + iA2zz*cos(qAL1)*cos(qAL2)^2*cos(qCy)*sin(qAL1) - iA2xx*cos(qAR1)*cos(qAR2)^2*cos(qCy)*sin(qAR1) + iA2zz*cos(qAR1)*cos(qAR2)^2*cos(qCy)*sin(qAR1) + lA2z^2*mA2*cos(qAL2)*sin(qAL1)*sin(qAL2)*sin(qCy) - lA2z^2*mA2*cos(qAR2)*sin(qAR1)*sin(qAR2)*sin(qCy) + LC*lA2z*mA2*sin(qAL1)*sin(qAL2)*sin(qCy) - LC*lA2z*mA2*sin(qAR1)*sin(qAR2)*sin(qCy) + lA2z*mA2*off*cos(qAL1)*cos(qCy)*sin(qAL2) + lA2z*mA2*off*cos(qAR1)*cos(qCy)*sin(qAR2) - lA2z^2*mA2*cos(qAL1)*cos(qAL2)^2*cos(qCy)*sin(qAL1) - lA2z^2*mA2*cos(qAR1)*cos(qAR2)^2*cos(qCy)*sin(qAR1);
B(1,3) = cos(qCy)*(cos(qAL1)*(cos(qAL2)*sin(qAL2)*(mA2*lA2z^2 + iA2xx) - iA2zz*cos(qAL2)*sin(qAL2)) + LC*lA2z*mA2*cos(qAL1)*sin(qAL2)) - sin(qCy)*(iA1zz + sin(qAL2)^2*(mA2*lA2z^2 + iA2xx) + iA2zz*cos(qAL2)^2 + lA2z*mA2*off*sin(qAL1)*sin(qAL2));
B(1,4) = cos(qCy)*(iA2yy*sin(qAL1) + lA2z^2*mA2*sin(qAL1) + lA2z*mA2*off*sin(qAL2) + LC*lA2z*mA2*cos(qAL2)*sin(qAL1)) + lA2z*mA2*off*cos(qAL1)*cos(qAL2)*sin(qCy);
B(1,5) = - cos(qCy)*(cos(qAR1)*(cos(qAR2)*sin(qAR2)*(mA2*lA2z^2 + iA2xx) - iA2zz*cos(qAR2)*sin(qAR2)) + LC*lA2z*mA2*cos(qAR1)*sin(qAR2)) - sin(qCy)*(iA1zz + sin(qAR2)^2*(mA2*lA2z^2 + iA2xx) + iA2zz*cos(qAR2)^2 + lA2z*mA2*off*sin(qAR1)*sin(qAR2));
