B(2,1) = B(1,2);
B(2,2) = 2*iA1xx + 2*iA2zz + iC2yy + 2*LC^2*mA1 + 2*LC^2*mA2 + 2*lA1z^2*mA1 + (lCz^2*mC)/2 - iA1xx*cos(qAL1)^2 + iA2xx*cos(qAL2)^2 + iA1yy*cos(qAL1)^2 + iA2yy*cos(qAL1)^2 - iA2zz*cos(qAL1)^2 - iA2zz*cos(qAL2)^2 - iA1xx*cos(qAR1)^2 + iA2xx*cos(qAR2)^2 + iA1yy*cos(qAR1)^2 + iA2yy*cos(qAR1)^2 - iA2zz*cos(qAR1)^2 - iA2zz*cos(qAR2)^2 - iA2xx*cos(qAL1)^2*cos(qAL2)^2 + iA2zz*cos(qAL1)^2*cos(qAL2)^2 - iA2xx*cos(qAR1)^2*cos(qAR2)^2 + iA2zz*cos(qAR1)^2*cos(qAR2)^2 + 4*LC*lA1z*mA1 + lA2z^2*mA2*cos(qAL1)^2 + lA2z^2*mA2*cos(qAL2)^2 + lA2z^2*mA2*cos(qAR1)^2 + lA2z^2*mA2*cos(qAR2)^2 - lA2z^2*mA2*cos(qAL1)^2*cos(qAL2)^2 - lA2z^2*mA2*cos(qAR1)^2*cos(qAR2)^2 + 2*LC*lA2z*mA2*cos(qAL2) + 2*LC*lA2z*mA2*cos(qAR2);
B(2,3) = -sin(qAL1)*sin(qAL2)*(mA2*cos(qAL2)*lA2z^2 + LC*mA2*lA2z + iA2xx*cos(qAL2) - iA2zz*cos(qAL2));
