% n(5) = fvA1*qAR1d - (iA1xx*qCyd^2*sin(2*qAR1))/2 + (iA1yy*qCyd^2*sin(2*qAR1))/2 + (iA2yy*qCyd^2*sin(2*qAR1))/2 - (iA2zz*qCyd^2*sin(2*qAR1))/2 - iA1xx*qCxd*qCyd*cos(qCy) - iA2xx*qCxd*qCyd*cos(qCy) + iA1yy*qCxd*qCyd*cos(qCy) + iA2yy*qCxd*qCyd*cos(qCy) - iA1zz*qCxd*qCyd*cos(qCy) - iA2zz*qCxd*qCyd*cos(qCy) - iA2xx*qAR2d*qCyd*sin(qAR1) - iA2yy*qAR2d*qCyd*sin(qAR1) + iA2zz*qAR2d*qCyd*sin(qAR1) + (lA2z^2*mA2*qCyd^2*sin(2*qAR1))/2 + iA2xx*qAR1d*qAR2d*sin(2*qAR2) - iA2zz*qAR1d*qAR2d*sin(2*qAR2) + iA2xx*qAR2d*qCxd*cos(qAR1)*cos(qCy) + iA2yy*qAR2d*qCxd*cos(qAR1)*cos(qCy) - iA2zz*qAR2d*qCxd*cos(qAR1)*cos(qCy) - 2*lA2z^2*mA2*qAR2d*qCyd*sin(qAR1) - iA2xx*qCyd^2*cos(qAR1)*cos(qAR2)^2*sin(qAR1) + iA2zz*qCyd^2*cos(qAR1)*cos(qAR2)^2*sin(qAR1) + iA1xx*qCxd^2*cos(qAR1)*cos(qCy)^2*sin(qAR1) - iA1yy*qCxd^2*cos(qAR1)*cos(qCy)^2*sin(qAR1) - iA2yy*qCxd^2*cos(qAR1)*cos(qCy)^2*sin(qAR1) + iA2zz*qCxd^2*cos(qAR1)*cos(qCy)^2*sin(qAR1) + 2*iA1xx*qCxd*qCyd*cos(qAR1)^2*cos(qCy) - 2*iA1yy*qCxd*qCyd*cos(qAR1)^2*cos(qCy) - 2*iA2yy*qCxd*qCyd*cos(qAR1)^2*cos(qCy) + 2*iA2zz*qCxd*qCyd*cos(qAR1)^2*cos(qCy) + lA2z^2*mA2*qAR1d*qAR2d*sin(2*qAR2) + 2*iA2xx*qAR2d*qCyd*cos(qAR2)^2*sin(qAR1) - 2*iA2zz*qAR2d*qCyd*cos(qAR2)^2*sin(qAR1) + 2*lA2z^2*mA2*qAR2d*qCxd*cos(qAR1)*cos(qCy) - lA2z*mA2*off*qCxd^2*cos(qAR1)*sin(qAR2) - g0*lA2z*mA2*cos(qAR1)*sin(qAR2)*sin(qCx) - 2*iA2xx*qAR2d*qCxd*cos(qAR2)*sin(qAR2)*sin(qCy) + 2*iA2zz*qAR2d*qCxd*cos(qAR2)*sin(qAR2)*sin(qCy) - lA2z^2*mA2*qCyd^2*cos(qAR1)*cos(qAR2)^2*sin(qAR1) - lA2z^2*mA2*qCxd^2*cos(qAR1)*cos(qCy)^2*sin(qAR1) - 2*lA2z^2*mA2*qCxd*qCyd*cos(qAR1)^2*cos(qCy) - 2*iA2xx*qAR2d*qCxd*cos(qAR1)*cos(qAR2)^2*cos(qCy) + 2*iA2zz*qAR2d*qCxd*cos(qAR1)*cos(qAR2)^2*cos(qCy) + 2*lA2z^2*mA2*qAR2d*qCyd*cos(qAR2)^2*sin(qAR1) + iA2xx*qCxd^2*cos(qAR1)*cos(qAR2)^2*cos(qCy)^2*sin(qAR1) - iA2zz*qCxd^2*cos(qAR1)*cos(qAR2)^2*cos(qCy)^2*sin(qAR1) + 2*iA2xx*qCxd*qCyd*cos(qAR1)^2*cos(qAR2)^2*cos(qCy) - 2*iA2zz*qCxd*qCyd*cos(qAR1)^2*cos(qAR2)^2*cos(qCy) - 2*lA2z^2*mA2*qAR2d*qCxd*cos(qAR2)*sin(qAR2)*sin(qCy) + 2*iA2xx*qCxd*qCyd*cos(qAR1)*cos(qAR2)*sin(qAR2)*sin(qCy) - 2*iA2zz*qCxd*qCyd*cos(qAR1)*cos(qAR2)*sin(qAR2)*sin(qCy) + g0*lA2z*mA2*cos(qCx)*sin(qAR1)*sin(qAR2)*sin(qCy) - 2*lA2z^2*mA2*qAR2d*qCxd*cos(qAR1)*cos(qAR2)^2*cos(qCy) + lA2z^2*mA2*qCxd^2*cos(qAR1)*cos(qAR2)^2*cos(qCy)^2*sin(qAR1) + 2*lA2z^2*mA2*qCxd*qCyd*cos(qAR1)^2*cos(qAR2)^2*cos(qCy) + iA2xx*qCxd^2*cos(qAR2)*cos(qCy)*sin(qAR1)*sin(qAR2)*sin(qCy) - iA2zz*qCxd^2*cos(qAR2)*cos(qCy)*sin(qAR1)*sin(qAR2)*sin(qCy) + 2*LC*lA2z*mA2*qCxd*qCyd*cos(qAR1)*sin(qAR2)*sin(qCy) + lA2z^2*mA2*qCxd^2*cos(qAR2)*cos(qCy)*sin(qAR1)*sin(qAR2)*sin(qCy) + LC*lA2z*mA2*qCxd^2*cos(qCy)*sin(qAR1)*sin(qAR2)*sin(qCy) + 2*lA2z^2*mA2*qCxd*qCyd*cos(qAR1)*cos(qAR2)*sin(qAR2)*sin(qCy);
% n(6) = fvA2*qAR2d + (mA2*lA2z^2 + iA2yy)*(qAR1d*(qCyd*sin(qAR1) - qCxd*cos(qAR1)*cos(qCy)) + qCxd*qCyd*sin(qAR1)*sin(qCy)) + (mA2*(cos(qAR2)*(LC*qCyd*cos(qAR1) + LC*qCxd*cos(qCy)*sin(qAR1) - off*qCxd*cos(qAR1)*sin(qCy)) + qCxd*cos(qCy)*sin(qAR2)*(off*cos(qAR1)^2 + off*sin(qAR1)^2)) + lA2z*mA2*(qCyd*cos(qAR1) - qAR2d + qCxd*cos(qCy)*sin(qAR1)))*(sin(qAR2)*(LC*qCyd*cos(qAR1) + LC*qCxd*cos(qCy)*sin(qAR1) - off*qCxd*cos(qAR1)*sin(qCy)) - qCxd*cos(qAR2)*cos(qCy)*(off*cos(qAR1)^2 + off*sin(qAR1)^2)) - ((mA2*lA2z^2 + iA2xx)*(cos(qAR2)*(qCyd*sin(qAR1) - qCxd*cos(qAR1)*cos(qCy)) + sin(qAR2)*(qAR1d - qCxd*sin(qCy))) - lA2z*mA2*(off*qCxd*sin(qAR1)*sin(qCy) - LC*qCyd*sin(qAR1) + LC*qCxd*cos(qAR1)*cos(qCy)))*(cos(qAR2)*(qAR1d - qCxd*sin(qCy)) - sin(qAR2)*(qCyd*sin(qAR1) - qCxd*cos(qAR1)*cos(qCy))) - mA2*(cos(qAR2)*(LC*qCyd*cos(qAR1) + LC*qCxd*cos(qCy)*sin(qAR1) - off*qCxd*cos(qAR1)*sin(qCy)) + qCxd*cos(qCy)*sin(qAR2)*(off*cos(qAR1)^2 + off*sin(qAR1)^2))*(sin(qAR2)*(LC*qCyd*cos(qAR1) + LC*qCxd*cos(qCy)*sin(qAR1) - off*qCxd*cos(qAR1)*sin(qCy)) - qCxd*cos(qAR2)*cos(qCy)*(off*cos(qAR1)^2 + off*sin(qAR1)^2)) + iA2zz*(cos(qAR2)*(qCyd*sin(qAR1) - qCxd*cos(qAR1)*cos(qCy)) + sin(qAR2)*(qAR1d - qCxd*sin(qCy)))*(cos(qAR2)*(qAR1d - qCxd*sin(qCy)) - sin(qAR2)*(qCyd*sin(qAR1) - qCxd*cos(qAR1)*cos(qCy))) + lA2z*mA2*(qAR2d*(sin(qAR2)*(LC*qCyd*cos(qAR1) + LC*qCxd*cos(qCy)*sin(qAR1) - off*qCxd*cos(qAR1)*sin(qCy)) - qCxd*cos(qAR2)*cos(qCy)*(off*cos(qAR1)^2 + off*sin(qAR1)^2)) - cos(qAR2)*(qAR1d*(off*qCxd*sin(qAR1)*sin(qCy) - LC*qCyd*sin(qAR1) + LC*qCxd*cos(qAR1)*cos(qCy)) + g0*sin(qAR1)*sin(qCx) + g0*cos(qAR1)*cos(qCx)*sin(qCy) - LC*qCxd*qCyd*sin(qAR1)*sin(qCy) - off*qCxd*qCyd*cos(qAR1)*cos(qCy)) + sin(qAR2)*(g0*cos(qCx)*cos(qCy) + qCxd*qCyd*sin(qCy)*(off*cos(qAR1)^2 + off*sin(qAR1)^2)));

B_passive = B(1:2,1:2);
B_off_diagonal = B(1:2,3:6);
n_passive = n(1:2);

expr_f_impl = vertcat(sym_xdot(1:6) - sym_x(7:12), ...
                      B_passive*sym_xdot(7:8) + B_off_diagonal*sym_xdot(9:12) + n_passive , ...
                      sym_xdot(9:12) - sym_u );

%% calculation of minimum distance between arms
posStartA = [0 ;  off ; 0];
posStartB = [0 ; -off ; 0];

posEndEffectorA = [-lArm*cos(qAL1)*sin(qAL2) ;  off + lArm*sin(qAL1)*sin(qAL2) ; -lArm*cos(qAL2)];
posEndEffectorB = [ lArm*cos(qAR1)*sin(qAR2) ; -off - lArm*sin(qAR1)*sin(qAR2) ; -lArm*cos(qAR2)];

unitVectorA = (posEndEffectorA-posStartA)/norm(posEndEffectorA-posStartA);
unitVectorB = (posEndEffectorB-posStartB)/norm(posEndEffectorB-posStartB);

k = unitVectorA'*unitVectorB;

tA0 = (posStartB-posStartA)'*(unitVectorA-k*unitVectorB)/(1-k^2+eps);
tB0 = (tA0-unitVectorA'*(posStartB-posStartA))/(k+eps);

tA = min(max(0,tA0),norm(posEndEffectorA-posStartA));
tB = min(max(0,tB0),norm(posEndEffectorB-posStartB));

minDistPointA = posStartA + tA*unitVectorA;
minDistPointB = posStartB + tB*unitVectorB;

minDist = min(norm(minDistPointA-minDistPointB),2*off);

%% nonlinear distance constraint
expr_h = minDist^2;

%% populate structure
model.nx = nx;
model.nu = nu;
model.sym_x = sym_x;
model.sym_xdot = sym_xdot;
model.sym_u = sym_u;
model.expr_f_impl = expr_f_impl;
model.expr_h = expr_h;

end
